/* cppi::dd30523598efdb387c60376b76a71ea0b63de249436ce2597fabc003b9de5cbe */
select security_type_name, esm_sec_type, cppib_sector_classification_name_1, cppib_sector_classification_name_2, cppib_sector_classification_name_3,* from cppib_enterprise_data_uat.enterprise_security_composite_tbl where business_date = date '2025-05-23'
and abor_security_number in ('FS1000126','FS1000132', 'FS1000206', 'FS1000207', 'FS1000210', 'PR1000019', 'PR1000024', 'PR1000032', 'PR1000034', 'PR1000044', 'PR1000132')

